from itertools import product
from urllib.parse import urlunsplit
from uuid import uuid4


def route_urls() -> tuple[str, ...]:
    optional_components = ("", uuid4().hex)
    return tuple(
        urlunsplit(
            (
                "https",
                f"{uuid4().hex}.invalid",
                f"/{uuid4().hex}",
                query,
                fragment,
            )
        )
        for query, fragment in product(optional_components, repeat=2)
    )

