def route_path(route_url: str) -> str:
    authority_start = route_url.index("://") + 3
    path_start = route_url.index("/", authority_start)
    path_end = len(route_url)
    for separator in ("?", "#"):
        separator_index = route_url.find(separator, path_start)
        if separator_index >= 0:
            path_end = min(path_end, separator_index)
    return route_url[path_start:path_end]

