from dataclasses import dataclass

REQUEST_FIELDS = {"unit_id": "unitId", "coverage_requirement": "coverageRequirement"}
REQUIRED_COVERAGE = "required"


@dataclass(frozen=True)
class SubmissionResult:
    accepted: bool


def create_valid_request() -> dict[str, str]:
    return {
        REQUEST_FIELDS["unit_id"]: "source-owned-unit",
        REQUEST_FIELDS["coverage_requirement"]: REQUIRED_COVERAGE,
    }


def submit_request(request: dict[str, str]) -> SubmissionResult:
    return SubmissionResult(
        accepted=bool(request[REQUEST_FIELDS["unit_id"]])
        and request[REQUEST_FIELDS["coverage_requirement"]] == REQUIRED_COVERAGE
    )
